    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LOW_PROFILE);usb=(UsbManager)getSystemService(USB_SERVICE);wifiManager=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);loadOui();build();IntentFilter wf=new IntentFilter(WifiManager.SCAN_RESULTS_AVAILABLE_ACTION);if(Build.VERSION.SDK_INT>=33)registerReceiver(wifiReceiver,wf,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(wifiReceiver,wf);wifiReceiverRegistered=true;bindService(new Intent(this,CydLinkService.class),serviceConnection,Context.BIND_AUTO_CREATE);if(!usb.getDeviceList().isEmpty())connect();ensurePhoneScan();}
