    final ServiceConnection serviceConnection=new ServiceConnection(){public void onServiceConnected(ComponentName name,IBinder binder){if(activityDestroyed)return;serviceBound=true;cydLink=((CydLinkService.LocalBinder)binder).service();cydLink.register(MainActivity.this);}public void onServiceDisconnected(ComponentName name){cydLink=null;gotAlive=false;if(!activityDestroyed)requestDraw();}};
    @Override public void onLines(List<String> lines){if(activityDestroyed)return;for(String line:lines)parse(line,false);requestDraw();}
