    void loadOui(){try(BufferedReader r=new BufferedReader(new InputStreamReader(getAssets().open("ieee_mac_registry.csv")))){String s;while((s=r.readLine())!=null){String[] p=s.split("\\|",3);if(p.length==3){ouiTypes.put(p[0],p[1]);oui.put(p[0],p[2]);}}}catch(Exception e){log("IEEE registry unavailable");}}
    String macHex(String mac){return mac==null?"":mac.replace(":","").replace("-","").toUpperCase(Locale.ROOT);}
    String ouiPrefix(String mac){String h=macHex(mac);if(h.length()!=12)return "";try{if((Integer.parseInt(h.substring(0,2),16)&3)!=0)return "LOCAL";}catch(Exception e){return "";}for(int n:new int[]{9,7,6})if(oui.containsKey(h.substring(0,n)))return h.substring(0,n);return "";}
    String vendor(String mac){String h=macHex(mac);if(h.length()!=12)return "UNASSIGNED";String prefix=ouiPrefix(mac);if(prefix.equals("LOCAL"))return "LOCAL / RANDOMIZED";return prefix.isEmpty()?"UNASSIGNED":oui.get(prefix);}
    String ouiRecord(String mac){String prefix=ouiPrefix(mac);if(prefix.equals("LOCAL"))return "LOCAL / RANDOMIZED";if(prefix.isEmpty())return "UNASSIGNED";return "OUI "+formatOui(prefix)+"  "+oui.get(prefix);}
    String formatOui(String prefix){return SignalClassifier.formatOui(prefix);}
    TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.create("monospace",bold?Typeface.BOLD:Typeface.NORMAL));if(Build.VERSION.SDK_INT>=28&&!bold)t.setTypeface(Typeface.create(Typeface.MONOSPACE,300,false));t.setIncludeFontPadding(false);return t;}
    android.graphics.drawable.Drawable surface(int stroke,int fill){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(fill);d.setStroke(dp(1),stroke);return d;}
